require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require __DIR__.'/../app/online_fulfillment.php'; require_permission('fulfill_online_orders');
$id=(int)($_GET['id']??$_POST['id']??0);$err='';$msg='';
if(!$id){$ids=is_super_admin()?[]:assigned_location_ids();$args=[];$scope='';if(!is_super_admin()){if(!$ids)$scope=' AND 1=0';else{$ph=implode(',',array_fill(0,count($ids),'?'));$scope=" AND NOT EXISTS(SELECT 1 FROM online_order_allocations x WHERE x.online_order_id=o.id AND x.location_id NOT IN ($ph))";$args=$ids;}}$st=db()->prepare("SELECT o.id,o.order_no,o.customer_name,o.status,o.created_at FROM online_orders o WHERE o.status IN ('ALLOCATED','PICKING')".$scope." ORDER BY o.id");$st->execute($args);$queue=$st->fetchAll();page_header('Godown Pick Queue');echo '<div class="panel"><b>Flow:</b> Open order → scan Rack/Bin code → scan garment barcode. Wrong rack or wrong item is rejected.</div><br><table><tr><th>Order</th><th>Customer</th><th>Status</th><th></th></tr>';foreach($queue as $q)echo '<tr><td>'.e($q['order_no']).'</td><td>'.e($q['customer_name']).'</td><td>'.e($q['status']).'</td><td><a class="btn" href="online_pick.php?id='.(int)$q['id'].'">Start Pick</a></td></tr>';echo '</table>';page_footer();exit;}
if(!can_access_online_order($id)){http_response_code(403);exit('Order outside your assigned locations.');}
// Called inside the pick transaction when the scan is not the exact reserved barcode.
// Returns the allocation to pick (after swapping in an identical AVAILABLE piece from the same bin) or throws a clear reason.
function pick_resolve_other(int $orderId,int $locId,string $barcode): array {
 $inOrder=function(int $pid) use($orderId){$st=db()->prepare("SELECT 1 FROM online_order_allocations WHERE online_order_id=? AND product_id=? AND status<>'RELEASED' LIMIT 1");$st->execute([$orderId,$pid]);return (bool)$st->fetchColumn();};
 $pendingElsewhere=function(int $pid) use($orderId,$locId){$st=db()->prepare("SELECT l.code FROM online_order_allocations a JOIN locations l ON l.id=a.location_id WHERE a.online_order_id=? AND a.product_id=? AND a.location_id<>? AND a.status IN ('RESERVED','PICKED') AND a.picked_qty<a.quantity LIMIT 1");$st->execute([$orderId,$pid,$locId]);return $st->fetchColumn()?:'';};
 $st=db()->prepare('SELECT ps.*,p.sku,p.product_name,l.code location_code FROM product_serials ps JOIN products p ON p.id=ps.product_id JOIN locations l ON l.id=ps.location_id WHERE ps.serial_barcode=? FOR UPDATE');$st->execute([$barcode]);$s=$st->fetch();
 if(!$s){
  $st=db()->prepare('SELECT p.id,p.sku,p.product_name,p.serial_tracking FROM products p WHERE p.product_barcode=? OR p.sku=? LIMIT 1');$st->execute([$barcode,$barcode]);$p=$st->fetch();
  if(!$p){$st=db()->prepare('SELECT p.id,p.sku,p.product_name,p.serial_tracking FROM batches b JOIN products p ON p.id=b.product_id WHERE b.batch_barcode=? LIMIT 1');$st->execute([$barcode]);$p=$st->fetch();}
  if(!$p)throw new Exception('BARCODE NOT FOUND — '.$barcode.' is not a product, lot or piece barcode.');
  $name=$p['sku'].' · '.$p['product_name'];
  if(!$inOrder((int)$p['id']))throw new Exception('WRONG PRODUCT — '.$name.' is not in this order.');
  if((int)$p['serial_tracking']===1)throw new Exception('Scan the unique piece label of '.$name.' (not the product / lot barcode).');
  $st=db()->prepare("SELECT 1 FROM online_order_allocations WHERE online_order_id=? AND product_id=? AND location_id=? AND status IN ('RESERVED','PICKED') AND picked_qty<quantity LIMIT 1");$st->execute([$orderId,$p['id'],$locId]);
  if($st->fetchColumn())throw new Exception('DIFFERENT LOT — scan the lot barcode shown in the list or the product barcode of '.$name.'.');
  $other=$pendingElsewhere((int)$p['id']);if($other!=='')throw new Exception($name.' is to be picked from rack/bin '.$other.'. Scan that rack first.');
  throw new Exception('ALREADY PICKED — the full quantity of '.$name.' is already picked.');
 }
 $name=$s['sku'].' · '.$s['product_name'];
 $st=db()->prepare("SELECT a.picked_qty,a.quantity,l.code FROM online_order_allocations a JOIN locations l ON l.id=a.location_id WHERE a.online_order_id=? AND a.serial_id=? AND a.status<>'RELEASED' LIMIT 1");$st->execute([$orderId,$s['id']]);$own=$st->fetch();
 if($own){if((float)$own['picked_qty']+0.0001>=(float)$own['quantity'])throw new Exception('ALREADY PICKED — this piece was already scanned for this order.');throw new Exception('This piece is listed at rack/bin '.$own['code'].'. Scan that rack first.');}
 if(!$inOrder((int)$s['product_id']))throw new Exception('WRONG PRODUCT — '.$name.' is not in this order.');
 if($s['status']==='RESERVED')throw new Exception('This piece is reserved for another order. Pick another piece of '.$name.'.');
 if($s['status']!=='AVAILABLE')throw new Exception('This piece is '.$s['status'].' and cannot be sent. Keep it aside and pick another piece.');
 if((int)$s['location_id']!==$locId)throw new Exception('LOCATION MISMATCH — the system has this piece in '.$s['location_code'].'. Return it there (or transfer it) before picking.');
 $st=db()->prepare("SELECT a.* FROM online_order_allocations a WHERE a.online_order_id=? AND a.location_id=? AND a.product_id=? AND a.serial_id IS NOT NULL AND a.status='RESERVED' AND a.picked_qty<a.quantity ORDER BY a.id LIMIT 1 FOR UPDATE");$st->execute([$orderId,$locId,$s['product_id']]);$a=$st->fetch();
 if(!$a){$other=$pendingElsewhere((int)$s['product_id']);if($other!=='')throw new Exception($name.' is to be picked from rack/bin '.$other.'. Scan that rack first.');throw new Exception('ALREADY PICKED — all pieces of '.$name.' are picked.');}
 // Swap: the scanned identical piece takes over the reservation of the piece listed on the order.
 if((int)$a['batch_id']!==(int)$s['batch_id']){
  $st=db()->prepare('SELECT qty,reserved_qty FROM inventory_balances WHERE product_id=? AND batch_id=? AND location_id=? FOR UPDATE');$st->execute([$s['product_id'],$s['batch_id'],$locId]);$nb=$st->fetch();
  if(!$nb||(float)$nb['qty']-(float)$nb['reserved_qty']<1)throw new Exception('Stock mismatch for this piece. Ask a manager to run a stock count before picking it.');
  $st=db()->prepare('SELECT 1 FROM inventory_balances WHERE product_id=? AND batch_id=? AND location_id=? FOR UPDATE');$st->execute([$a['product_id'],$a['batch_id'],$locId]);
  db()->prepare('UPDATE inventory_balances SET reserved_qty=GREATEST(reserved_qty-1,0) WHERE product_id=? AND batch_id=? AND location_id=?')->execute([$a['product_id'],$a['batch_id'],$locId]);
  db()->prepare('UPDATE inventory_balances SET reserved_qty=reserved_qty+1 WHERE product_id=? AND batch_id=? AND location_id=?')->execute([$s['product_id'],$s['batch_id'],$locId]);
 }
 db()->prepare("UPDATE product_serials SET status='AVAILABLE' WHERE id=? AND status='RESERVED'")->execute([$a['serial_id']]);
 $up=db()->prepare("UPDATE product_serials SET status='RESERVED' WHERE id=? AND status='AVAILABLE'");$up->execute([$s['id']]);if($up->rowCount()!==1)throw new Exception('This piece was just taken by another user. Scan another piece.');
 db()->prepare('UPDATE online_order_allocations SET serial_id=?,batch_id=? WHERE id=?')->execute([$s['id'],$s['batch_id'],$a['id']]);
 audit('ONLINE_PICK_SWAP','online_order',$orderId,['allocation_id'=>(int)$a['id'],'from_serial_id'=>(int)$a['serial_id'],'to_serial_id'=>(int)$s['id']]);
 $a['serial_id']=$s['id'];$a['batch_id']=$s['batch_id'];$a['sku']=$s['sku'];$a['product_name']=$s['product_name'];$a['swapped']=true;
 return $a;
}
$st=db()->prepare('SELECT * FROM online_orders WHERE id=?');$st->execute([$id]);$order=$st->fetch();if(!$order)exit('Order not found');
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';try{
 if($action==='scan_location'){$code=trim($_POST['location_code']??'');$ids=is_super_admin()?online_order_location_ids($id):assigned_location_ids();if(!$ids)throw new Exception('No assigned locations.');$ph=implode(',',array_fill(0,count($ids),'?'));$st=db()->prepare("SELECT l.id,l.code FROM locations l WHERE l.code=? AND l.id IN ($ph) AND EXISTS(SELECT 1 FROM online_order_allocations a WHERE a.online_order_id=? AND a.location_id=l.id AND a.status IN ('RESERVED','PICKED') AND a.picked_qty<a.quantity) LIMIT 1");$st->execute([$code,...$ids,$id]);$loc=$st->fetch();if(!$loc)throw new Exception('Wrong rack/bin for this order, or this rack is already complete.');$_SESSION['pick_location_'.$id]=(int)$loc['id'];$msg='Rack/Bin accepted: '.$loc['code'].'. Now scan item.';}
 elseif($action==='scan_item'){$locId=(int)($_SESSION['pick_location_'.$id]??0);if(!$locId||!can_access_location($locId))throw new Exception('Scan the correct rack/bin code first.');$barcode=trim($_POST['barcode']??'');if($barcode==='')throw new Exception('Scan item barcode.');db()->beginTransaction();$st=db()->prepare('SELECT status FROM online_orders WHERE id=? FOR UPDATE');$st->execute([$id]);$os=$st->fetchColumn();if(!in_array($os,['ALLOCATED','PICKING'],true))throw new Exception('Order is not in picking state.');$sql="SELECT a.*,ps.serial_barcode,b.batch_barcode,p.product_barcode,p.sku,p.product_name FROM online_order_allocations a LEFT JOIN product_serials ps ON ps.id=a.serial_id JOIN batches b ON b.id=a.batch_id JOIN products p ON p.id=a.product_id WHERE a.online_order_id=? AND a.location_id=? AND a.status IN ('RESERVED','PICKED') AND a.picked_qty<a.quantity AND (ps.serial_barcode=? OR (a.serial_id IS NULL AND (b.batch_barcode=? OR p.product_barcode=?))) ORDER BY a.id LIMIT 1 FOR UPDATE";$st=db()->prepare($sql);$st->execute([$id,$locId,$barcode,$barcode,$barcode]);$a=$st->fetch();if(!$a)$a=pick_resolve_other($id,$locId,$barcode);$new=(float)$a['picked_qty']+1;$status=$new+0.0001>=(float)$a['quantity']?'PICKED':'RESERVED';db()->prepare('UPDATE online_order_allocations SET picked_qty=?,status=?,picked_by=?,picked_at=NOW() WHERE id=?')->execute([$new,$status,current_user()['id'],$a['id']]);$t=online_order_totals($id);$complete=(float)$t['picked']+0.0001>=(float)$t['total'];db()->prepare('UPDATE online_orders SET status=? WHERE id=?')->execute([$complete?'PICKED':'PICKING',$id]);db()->commit();$msg='PICK OK · '.$a['sku'].' · '.$a['product_name'].(!empty($a['swapped'])?' (scanned piece replaced the listed piece)':'');if($complete){unset($_SESSION['pick_location_'.$id]);publish_event('ONLINE_PICK_COMPLETE','Online order picked',online_order_number($id).' · ready for packing',['super_admin'],'online_order',$id,null);publish_scoped_event('ONLINE_PICK_COMPLETE','Order picked',online_order_number($id).' · ready for packing',['manager','godown'],'online_order',$id);}
 }else throw new Exception('Invalid action.');
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
$st=db()->prepare("SELECT a.*,p.sku,p.product_barcode,p.product_name,p.color,p.size,p.product_image,l.code location_code,l.warehouse,l.rack,l.shelf_bin,b.batch_barcode,ps.serial_barcode,(SELECT COALESCE(SUM(ib.qty),0) FROM inventory_balances ib WHERE ib.product_id=a.product_id AND ib.location_id=a.location_id) bin_qty FROM online_order_allocations a JOIN products p ON p.id=a.product_id JOIN locations l ON l.id=a.location_id JOIN batches b ON b.id=a.batch_id LEFT JOIN product_serials ps ON ps.id=a.serial_id WHERE a.online_order_id=? AND a.status<>'RELEASED' ORDER BY l.code,p.sku,a.id");$st->execute([$id]);$alloc=$st->fetchAll();$t=online_order_totals($id);$cur=(int)($_SESSION['pick_location_'.$id]??0);$curCode='';foreach($alloc as $a)if((int)$a['location_id']===$cur){$curCode=$a['location_code'];break;}page_header('Pick Order '.e($order['order_no']));if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
